// Run one creation command. Returns the process exit code; nothing is written
// to stdout except the single result document.
export async function runCreateTourCommand(
  kind: TourKind,
  argv: string[],
  io: CreationCommandIO = consoleIO
): Promise<number> {
  try {
    const parsed = parseArguments(argv);
    if (parsed.help) {
      // Exit 0 means a Tour was created, so usage text never travels on
      // stdout: an explicit help request is a usage answer, and stdout stays
      // empty.
      io.err(usage(kind));
      return EXIT_USAGE;
    }
    const workspaceRoot = resolveWorkspace(parsed.workspace as string);
    const proposal = await readProposal(parsed.proposal);
    const result = await create(kind, workspaceRoot, proposal);
    if (!result.ok) {
      io.out(JSON.stringify(failureDocument(result)));
      reportFailure(io, result);
      return EXIT_REFUSED;
    }
    io.out(
      JSON.stringify({
        ok: true,
        kind: result.kind,
        tourPath: result.tourPath,
        title: result.title,
        stepCount: result.stepCount,
        warnings: result.warnings,
      })
    );
    return EXIT_CREATED;
  } catch (error) {
    if (error instanceof CreationUsageError) {
      io.err(`CodeTour: ${error.message}`);
      io.err(usage(kind));
      return EXIT_USAGE;
    }
    if (error instanceof ProposalSyntaxError) {
      const failure: CreationFailure = {
        ok: false,
        code: "INVALID_PROPOSAL",
        message: error.message,
      };
      io.out(JSON.stringify(failureDocument(failure)));
      reportFailure(io, failure);
      return EXIT_REFUSED;
    }
    // An unclassified failure still owes the caller one JSON document on
    // stdout: exit 1 promises a failure document, and an empty stdout would
    // read as a crash the skill cannot act on.
    const failure: CreationFailure = {
      ok: false,
      code: "INTERNAL_ERROR",
      message: error instanceof Error ? error.message : String(error),
    };
    io.out(JSON.stringify(failureDocument(failure)));
    io.err(`CodeTour: internal error: ${failure.message}`);
    if (error instanceof Error && error.stack !== undefined) {
      io.err(error.stack);
    }
    return EXIT_REFUSED;
  }
}

